+    fn idle_storage_release_preserves_fragments_progress_and_reuse() {
+        let mut hs = HandshakeDeframer::default();
+        assert!(hs.spans.capacity() >= 16);
+        hs.discard_empty_storage();
+        assert_eq!(hs.spans.capacity(), 0);
